import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import io from "socket.io-client";
import './DMPage.css';

// Use a common socket instance (ideally import from a shared module)
const socket = io("http://localhost:5001", { transports: ["websocket"] });

const DMPage = ({ currentUser }) => {
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);          // All messages received
  const [newMessage, setNewMessage] = useState('');
  const [dmList, setDmList] = useState([]);                // List of users with whom we have a conversation
  const [selectedChat, setSelectedChat] = useState(null);  // The currently selected conversation (user)
  const [conversations, setConversations] = useState([]);  // Raw conversation objects (if needed)
  const messagesEndRef = useRef(null);

  // Scroll to the latest message when messages change
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // Register current user and set up socket listeners
  useEffect(() => {
    if (currentUser?._id) {
      console.log("Registering user on socket:", currentUser._id);
      socket.emit("register", currentUser._id);
    }

    // Listener: When a new message is received
    const handleReceiveMessage = (message) => {
      console.log("Received message:", message);
      setMessages(prev => [...prev, message]);

      // Ensure sender is in DM list: compare as strings
      if (!dmList.some(user => String(user._id) === String(message.sender))) {
        console.log("Sender not in DM list. Requesting details for:", message.sender);
        socket.emit("addToDM", message.sender);
      }
    };

    socket.on("receiveMessage", handleReceiveMessage);

    // Listener: When a DM update is received (user details)
    const handleAddToDM = (newUser) => {
      console.log("Received addToDM event with user:", newUser);
      // Avoid duplicates by comparing string IDs
      setDmList(prev => {
        if (prev.some(user => String(user._id) === String(newUser._id))) {
          return prev;
        }
        return [...prev, newUser];
      });
    };

    socket.on("addToDM", handleAddToDM);

    // Listener: When a new conversation is created/exists
    const handleNewConversation = (conversation) => {
      console.log("🆕 New conversation received:", conversation);
      setConversations(prev => [...prev, conversation]);

      // Determine the other participant by normalizing IDs as strings
      const otherParticipant = conversation.participants.find(u => String(u) !== String(currentUser._id));
      if (otherParticipant) {
        // Check if we already have this user in our DM list
        setDmList(prev => {
          if (prev.some(user => String(user._id) === String(otherParticipant))) {
            return prev;
          }
          // Add placeholder details if no full info is available
          console.log("Other participant not in DM list. Adding placeholder for:", otherParticipant);
          return [...prev, { _id: otherParticipant, name: "Unknown", role: "applicant", image: "default_user_image.jpg" }];
        });
      }
    };

    socket.on("newConversation", handleNewConversation);

    // Clean up listeners on unmount
    return () => {
      socket.off("receiveMessage", handleReceiveMessage);
      socket.off("addToDM", handleAddToDM);
      socket.off("newConversation", handleNewConversation);
    };
  }, [currentUser]); // Only depend on currentUser to avoid repeated re-attachment of listeners

  // Send a message to the selected conversation
  const handleSend = () => {
    if (newMessage.trim() && selectedChat) {
      const messageData = {
        sender: currentUser._id,
        receiver: selectedChat._id,
        message: newMessage,
      };
      console.log("Sending message:", messageData);
      socket.emit("sendMessage", messageData);
      setNewMessage('');
    } else {
      console.warn("No conversation selected or message is empty.");
    }
  };

  // Handle Accept button (for client users)
  const handleAccept = () => {
    console.log("Accepting conversation with:", selectedChat);
    // Remove all other conversations for the client by keeping only the accepted one in DM list
    setDmList([selectedChat]);
    // Navigate to CreateTimeline (ensure route is defined accordingly)
    navigate("/createTimeline");
  };

  return (
    <div className="dm-container">
      {/* Header Section with Navigation */}
      <div className="header">
        <img src="images/image10.png" alt="User" />
        <div className="header-right">
          <span onClick={() => navigate("/homes")}>Home</span>
          <span onClick={() => navigate("/profile")}>Profile</span>
          <span onClick={() => navigate("/ong-proj")}>Ongoing Projects</span>
          <span onClick={() => navigate("/post")}>Post a Job</span>
          <span onClick={() => navigate("/contact")}>Contact Us</span>
          <span onClick={() => navigate("/abt")}>About</span>
        </div>
      </div>

      <div className="dm-main">
        {/* Sidebar: DM List */}
        <div className="dm-sidebar">
          <h2>Conversations</h2>
          {dmList.map((user) => (
            <div 
              key={user._id} 
              className={`active-chat ${selectedChat && String(selectedChat._id) === String(user._id) ? "selected" : ""}`}
              onClick={() => {
                console.log("Selected conversation with:", user);
                setSelectedChat(user);
              }}
            >
              <div className="user-avatar">
                <img src={user.image || "default_user_image.jpg"} alt={user.name || "User"} />
              </div>
              <div className="user-info">
                <h3>{user.name || "Unknown"}</h3>
                <p>{user.role || ""}</p>
              </div>
            </div>
          ))}
        </div>

        {/* Chat Window */}
        <div className="chat-window">
          {selectedChat ? (
            <>
              <div className="messages-container">
                {messages
                  .filter(msg => (
                    String(msg.sender) === String(selectedChat._id) ||
                    String(msg.receiver) === String(selectedChat._id)
                  ))
                  .map((msg, index) => (
                    <div key={index} className={`message ${String(msg.sender) === String(currentUser._id) ? 'sent' : 'received'}`}>
                      <div className="message-content">
                        <div className="message-header">
                          <span className="sender">
                            {String(msg.sender) === String(currentUser._id) ? "You" : selectedChat.name}
                          </span>
                          <span className="timestamp">{new Date().toLocaleTimeString()}</span>
                        </div>
                        <p>{msg.message}</p>
                      </div>
                    </div>
                  ))}
                <div ref={messagesEndRef} />
              </div>

              <div className="message-input">
                <input
                  type="text"
                  value={newMessage}
                  onChange={(e) => setNewMessage(e.target.value)}
                  placeholder="Type your message..."
                  onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                />
                <button onClick={handleSend}>
                  <svg viewBox="0 0 24 24" width="24" height="24">
                    <path fill="currentColor" d="M2.01 21L23 12 2.01 3 2 10l15 2-15 2z"/>
                  </svg>
                </button>
              </div>

              {/* If the current user is a client, show the Accept button */}
              {currentUser.role === "client" && (
                <div className="accept-section">
                  <button onClick={handleAccept} className="accept-btn">
                    Accept
                  </button>
                </div>
              )}
            </>
          ) : (
            <div className="empty-chat">
              <p>Select a conversation to start chatting</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default DMPage;
